parameters.jsCode:
// Merge LinkedIn and Instagram outputs with the topic data
const topicData = $('Code - Pick Random Topic').first().json;

// Get the generated contents
const linkedinData = $input.first().json;
const linkedinPost = linkedinData.content ? linkedinData.content[0].text : '';

// Instagram data comes from second input
let instagramCaption = '';
if ($input.length > 1) {
  const igData = $input.all()[1].json;
  instagramCaption = igData.content ? igData.content[0].text : '';
}

const hashtags = topicData.hashtags.join(' ');

return [{
  json: {
    theme: topicData.theme,
    angle: topicData.angle,
    tone: topicData.tone,
    format: topicData.format,
    linkedin_post: linkedinPost,
    instagram_caption: instagramCaption,
    hashtags: hashtags,
    created_at: new Date().toISOString(),
    status: 'draft'
  }
}];

